  t24 = t3 * t23;
  t25 = POW_1_3(t4);
  t26 = t24 * t25;
  t27 = sigma[0] * sigma[0];
  t28 = t27 * sigma[0];
  t29 = rho[0] * rho[0];
  t30 = t29 * t29;
  t31 = t30 * t30;
  t32 = 0.1e1 / t31;
  t34 = POW_1_3(rho[0]);
  t35 = t34 * t34;
